ext('c12_eng_ch16',[
C("🪦","एपिटाफ़ क्या होता है",["समाधि या क़ब्र पर लिखा लेख","छोटा, भावपूर्ण","मृत व्यक्ति की स्मृति","कविता का एक विशेष रूप"],"कविता का शीर्षक है एन एपिटाफ़। एपिटाफ़ का अर्थ है वह छोटा सा लेख जो किसी की समाधि या क़ब्र पर लिखा जाता है। इसमें मृत व्यक्ति का नाम, उसके गुण या उसके बारे में कोई भावपूर्ण पंक्ति होती है। कई बार कवि सचमुच किसी की समाधि के लिए लिखते हैं, और कई बार यह साहित्यिक रूप में एक कविता बन जाता है। इस कविता में भी कवि एक सुंदर स्त्री की स्मृति में शब्द लिखते हैं और उसके माध्यम से जीवन की नश्वरता पर विचार करते हैं। यह रूप छोटा होता है, पर भाव गहरा।"),
C("✍️","वॉल्टर डे ला मेयर",["इंग्लैंड के कवि और उपन्यासकार","कल्पना, रहस्य और बचपन के विषय","द लिसनर प्रसिद्ध कविता","सरल पर गहरी भाषा"],"कवि वॉल्टर डे ला मेयर इंग्लैंड के प्रसिद्ध कवि और उपन्यासकार थे। उनकी रचनाओं में कल्पना, रहस्य, स्वप्न और बचपन की झलक मिलती है। उनकी कविता द लिसनर बहुत प्रसिद्ध है। उनकी भाषा सरल रहती है, पर उसके भीतर गहरा अर्थ छिपा होता है। वे बच्चों के लिए भी लिखते थे और बड़ों के लिए भी। इस कविता में भी वे सीधे शब्दों में बहुत बड़ी बात कहते हैं। परीक्षा के लिए उनका नाम, देश और उनकी रचनाओं की मुख्य विशेषताएँ, यानी कल्पना और रहस्य, याद रखिए।"),
C("💃","सुंदर स्त्री का चित्र",["हल्के क़दमों से चलने वाली","आकर्षक व्यक्तित्व","जीवन से भरी","अब केवल स्मृति"],"कविता में जिस स्त्री का वर्णन है, वह बहुत सुंदर और हल्के क़दमों से चलने वाली थी। उसका व्यक्तित्व आकर्षक था और वह जीवन से भरी हुई थी। पर अब वह केवल एक समाधि में है। इस तुलना से कवि सुंदरता और जीवन की क्षणभंगुरता को उभारते हैं। जो चेहरा कभी सबका ध्यान खींचता था, वह अब केवल यादों में रह गया है। पाठक के मन में एक हल्की कसक उठती है, और यही कविता का असर है। कवि बिना रोए, बहुत शांत स्वर में यह बात कहते हैं।"),
C("❓","कवि के प्रश्न",["कौन याद रखेगा","समय सब कुछ मिटा देता है","प्रश्न से भाव गहरा होता है","पाठक को सोचने पर मजबूर करना"],"इस कविता की ख़ास तकनीक है कि कवि सीधे कुछ बताने की जगह प्रश्न करते हैं। वे सोचते हैं कि इस सुंदर स्त्री को और उसकी सुंदरता को आगे कौन याद रखेगा। यह प्रश्न पाठक को भी सोचने पर मजबूर करता है। प्रश्न का प्रयोग कविता में रहस्य और भावुकता दोनों बढ़ाता है। इसे रेटॉरिकल क्वेश्चन कहते हैं, यानी ऐसा प्रश्न जिसका उत्तर देना ज़रूरी नहीं, बल्कि जो विचार जगाने के लिए पूछा जाता है। परीक्षा में काव्य सौंदर्य में इसे अवश्य लिखिए।"),
C("⏳","नश्वरता का विचार",["सुंदरता क्षणिक है","जीवन अस्थायी है","समय का प्रवाह निरंतर","स्मृतियाँ भी धुँधली होती हैं"],"कविता का केंद्रीय विचार नश्वरता है, यानी हर चीज़ का एक दिन समाप्त होना। सुंदरता, युवावस्था, यहाँ तक कि हमारी यादें भी समय के साथ फीकी पड़ जाती हैं। साहित्य में यह विचार बहुत पुराना है। हमारे यहाँ भी कहा गया है कि यह शरीर नश्वर है और कर्म ही अमर रहते हैं। पर कवि इसे उदासी से नहीं, शांत स्वीकार के साथ कहते हैं। इससे पाठक को डर नहीं, बल्कि जीवन की क़ीमत का एहसास होता है। जो चीज़ सीमित है, वह और भी क़ीमती लगती है।"),
C("🌸","वर्तमान को जीना",["आज का समय सबसे क़ीमती","अपनों के साथ समय बिताएँ","अच्छे कर्म स्मृति बनते हैं","कल की चिंता में आज न खोएँ"],"नश्वरता का यह विचार हमें एक सकारात्मक सीख भी देता है। जब हम जानते हैं कि समय सीमित है, तो हम वर्तमान को ज़्यादा ध्यान से जीते हैं। अपनों के साथ समय बिताना, अच्छे काम करना और पढ़ाई में मन लगाना, यही असली पूँजी है। अच्छे कर्म ही दूसरों की यादों में हमारी जगह बनाते हैं। कविता यह नहीं कहती कि निराश हो जाओ, बल्कि यह कहती है कि जो पल अभी तुम्हारे पास है, उसे सुंदर बनाओ। यही इस कविता की सबसे उपयोगी सीख है।"),
C("🎼","भाषा और शैली",["सरल शब्द","शोक गीत का स्वर","छोटी पंक्तियाँ","ठहराव और मौन"],"इस कविता की भाषा सरल है, जिसमें कठिन शब्द कम हैं। इसका स्वर शोकगीत जैसा है, जिसे अंग्रेज़ी में एलेजी कहते हैं, यानी किसी के निधन पर लिखा गया भावपूर्ण गीत। पंक्तियाँ छोटी हैं, जिनमें ठहराव और मौन की जगह है। इन ठहरावों में पाठक अपने मन की बात जोड़ सकता है। कविता का प्रवाह शांत और धीमा है, जो विषय की गंभीरता से पूरी तरह मेल खाता है। परीक्षा में शैली पर पूछा जाए, तो सरल भाषा, शोक का स्वर और प्रश्न की तकनीक लिखिए।"),
C("📝","शब्दार्थ दोहराइए",["एपिटाफ़ यानी समाधि-लेख","ग्रेव यानी क़ब्र","ट्रांज़िएंट यानी क्षणिक","मेमोरी यानी स्मृति"],"आइए कुछ ज़रूरी शब्द दोहरा लें। एपिटाफ़ यानी समाधि-लेख, ग्रेव यानी क़ब्र, ट्रांज़िएंट यानी क्षणिक, मेमोरी यानी स्मृति, और मॉर्टैलिटी यानी नश्वरता। साथ में ब्यूटी यानी सुंदरता, फ़ेड यानी फीका पड़ना और लाइट फ़ुटेड यानी हल्के क़दमों वाला भी याद कर लीजिए। अब हर शब्द से अपना एक अंग्रेज़ी वाक्य बनाइए। जैसे ब्यूटी इज़ ट्रांज़िएंट, यानी सुंदरता क्षणिक है। और मेमोरीज़ फ़ेड विद टाइम, यानी यादें समय के साथ फीकी हो जाती हैं। इन्हें कॉपी में लिखिए।"),
C("🧩","व्याकरण: रेटॉरिकल क्वेश्चन",["उत्तर की अपेक्षा नहीं","विचार जगाने के लिए","अंग्रेज़ी में हू विल रिमेंबर","निबंध और भाषण में उपयोगी"],"कविता में कवि ने जो प्रश्न पूछे हैं, उन्हें रेटॉरिकल क्वेश्चन कहते हैं। इनमें प्रश्न पूछने वाला उत्तर नहीं चाहता, वह केवल सुनने वाले को सोचने पर मजबूर करना चाहता है। जैसे हू विल रिमेंबर अस आफ़्टर ए हंड्रेड ईयर्स, यानी सौ साल बाद हमें कौन याद रखेगा। इस तकनीक का इस्तेमाल भाषण, निबंध और विज्ञापन में भी होता है, क्योंकि यह श्रोता को जोड़ता है। अपने लेखन में भी एक या दो रेटॉरिकल प्रश्न डालिए, इससे आपकी भाषा प्रभावशाली लगती है।"),
C("🌿","संसार में स्मृति के रूप",["समाधि और स्मारक","किताबें और कला","अच्छे कर्म और विचार","बिहार में पूर्वजों का स्मरण"],"मनुष्य अपनी स्मृति को सुरक्षित रखने के कई तरीक़े अपनाता है। समाधि और स्मारक, किताबें, कलाकृतियाँ और अच्छे कर्म, सब स्मृति के रूप हैं। हमारे बिहार में पितृपक्ष पर पूर्वजों का स्मरण किया जाता है और गया में पिंडदान की परंपरा है। यह दिखाता है कि हम अपने पूर्वजों की याद को कितना महत्व देते हैं। यह कविता भी इसी भाव से जुड़ती है, पर वह सोचती है कि जब कोई याद करने वाला न रहे, तो क्या होगा। इस विचार को लेकर अपने शब्दों में एक छोटा अनुच्छेद लिखिए।"),
C("📌","कविता का सार",["समाधि पर एक सुंदर स्त्री की स्मृति","कवि का प्रश्न: कौन याद रखेगा","सुंदरता और जीवन की नश्वरता","संदेश: वर्तमान को सार्थक जिएँ"],"अब कविता का सार दोहरा लें। वॉल्टर डे ला मेयर की इस कविता में एक सुंदर और हल्के क़दमों वाली स्त्री की समाधि के बहाने कवि सुंदरता और जीवन की नश्वरता पर विचार करते हैं। वे प्रश्न पूछते हैं कि उसकी सुंदरता को कौन याद रखेगा। संदेश यह है कि जीवन और सौंदर्य क्षणिक हैं, इसलिए हमें वर्तमान को अर्थपूर्ण ढंग से जीना चाहिए। इसे अपने शब्दों में पाँच वाक्यों में लिखकर देखिए।"),
C("❓","संभावित परीक्षा प्रश्न",["कवि कौन हैं","एपिटाफ़ का अर्थ","कविता का केंद्रीय भाव","कविता से क्या सीख मिलती है"],"परीक्षा के प्रश्न देखिए। पहला, कवि कौन हैं? उत्तर, वॉल्टर डे ला मेयर, इंग्लैंड के कवि। दूसरा, एपिटाफ़ का अर्थ? उत्तर, समाधि पर लिखा जाने वाला लेख। तीसरा, केंद्रीय भाव? उत्तर, सुंदरता और जीवन की नश्वरता। चौथा, क्या सीख मिलती है? उत्तर, कि जीवन क्षणिक है और हमें वर्तमान को सार्थक ढंग से जीना चाहिए। पूरे वाक्य में उत्तर लिखिए और कविता की किसी एक विशेषता का उल्लेख कीजिए।"),
Q("आपके अनुसार किसी व्यक्ति को सबसे अच्छे तरीक़े से कैसे याद रखा जा सकता है?","उसके अच्छे कर्म, विचार और व्यवहार को आगे बढ़ाकर, क्योंकि वही असली स्मृति है।","एक सोचने वाला प्रश्न। आपके अनुसार किसी व्यक्ति को सबसे अच्छे तरीक़े से कैसे याद रखा जा सकता है? सोचिए। ... उसके अच्छे कर्म, विचार और व्यवहार को आगे बढ़ाकर, क्योंकि वही असली स्मृति है। केवल समाधि से नहीं, अच्छे काम से कोई याद रहता है।"),
],7)
